package io.knowledgebrain.collaboration;
import io.knowledgebrain.contracts.collaboration.course.v1.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;
import org.apache.kafka.clients.consumer.*;import org.apache.kafka.common.serialization.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_GROUP_KAFKA_BOOTSTRAP",matches=".+")
class CourseKafkaIntegrationTest {
 @Test void orderedCourseCdcBytesAndUnacknowledgedReplay()throws Exception{
  var f=new CourseStoreIntegrationTest();f.setup();var a=f.study();var v=f.create(f.f.key()).course();var selected=f.curriculum(v,a.studyId());var active=f.state(selected,"ACTIVE");f.state(active,"COMPLETED");var expected=new HashMap<String,byte[]>();for(var bytes:f.f.jdbc.queryForList("SELECT payload FROM outbox_event WHERE aggregateid=?",byte[].class,v.courseId())){var e=CourseEnvelopeV1.parseFrom(bytes);expected.put(e.getEventId(),bytes);}assertEquals(4,expected.size());
  var options=new Properties();options.put("bootstrap.servers",System.getenv("BRAIN_TEST_GROUP_KAFKA_BOOTSTRAP"));options.put("group.id","group-validation-"+UUID.randomUUID());options.put("enable.auto.commit","false");options.put("auto.offset.reset","earliest");options.put("key.deserializer",StringDeserializer.class.getName());options.put("value.deserializer",ByteArrayDeserializer.class.getName());options.put("security.protocol","SSL");options.put("ssl.endpoint.identification.algorithm","HTTPS");options.put("ssl.truststore.type","PEM");options.put("ssl.keystore.type","PEM");options.put("ssl.truststore.certificates",Files.readString(Path.of("/group-kafka-test/ca.crt")));options.put("ssl.keystore.certificate.chain",Files.readString(Path.of("/group-kafka-test/user.crt")));options.put("ssl.keystore.key",Files.readString(Path.of("/group-kafka-test/user.key")));
  for(int replay=0;replay<2;replay++){var seen=new HashSet<String>();try(var consumer=new KafkaConsumer<String,byte[]>(options)){consumer.subscribe(List.of("collaboration.course.v1"));long deadline=System.nanoTime()+Duration.ofSeconds(60).toNanos();while(seen.size()<4&&System.nanoTime()<deadline)for(var record:consumer.poll(Duration.ofMillis(300))){var e=CourseEnvelopeV1.parseFrom(record.value());if(!expected.containsKey(e.getEventId()))continue;assertArrayEquals(expected.get(e.getEventId()),record.value());assertEquals(e.getAggregateId(),record.key());assertEquals(f.f.trace,e.getTraceId());assertEquals(f.space.toString(),e.getSpaceId());assertEquals("Course",e.getAggregateType());var p=CourseSnapshotV1.parseFrom(e.getPayload());assertEquals(v.courseId().toString(),p.getCourseId());assertEquals("PRIVATE",p.getVisibility());assertEquals("collaboration.course.v1",record.topic());if(p.getVersion()>1){assertEquals(a.studyId().toString(),p.getStudies(0).getStudyId());assertEquals(1,p.getStudies(0).getStudyVersion());}for(var entry:Map.of("trace_id",f.f.trace,"schema_group","collaboration","schema_artifact","course-events","schema_version","1").entrySet())assertEquals(entry.getValue(),new String(record.headers().lastHeader(entry.getKey()).value(),StandardCharsets.UTF_8));seen.add(e.getEventId());}}assertEquals(expected.keySet(),seen);}
  System.out.println("PASS collaboration.course.v1 four byte-exact Course snapshots, stable IDs, trace/schema headers and unacknowledged replay");
 }
}
